operations.document:
mutation AddTodoFormMutation($input: AddTodoInput!) {
  addTodo(input: $input) {
    id
    title
  }
}

query TodoDetailQuery($id: ID!) {
  todo(id: $id) {
    id
    title
    done
    status
    owner {
      name
    }
  }
}

mutation TodoDetailToggleMutation($id: ID!) {
  toggleTodo(id: $id) {
    id
    done
  }
}

query UserListQuery {
  users {
    id
    name
    email
  }
}

fragments.document:
fragment TodoItem_todo on Todo {
  title
  done
}
